from typing import Any, Optional, Union  # noqa: F401

from taf.internal.aliasing import aliasing_scope
from taf.internal.robot_typecasts import time_to_seconds

from .facade import OpticalSwitch


class optical_switch:
    """
    Usage example:
        >>> from taf.hw.optical_switch import optical_switch
        >>> switch = optical_switch()
        >>> switch.setup_optical_switch(optical_switch='Leoni', model='mol 6x(2x6)', addr='127.0.0.1')
        >>> switch.get_optical_switch_channels()
        {1:2, 2:2, 3:1, 4:4}
        >>> switch.set_optical_switch_channels({2:3, 4:1})
        >>> switch.get_optical_switch_channels()
        {1:2, 2:3, 3:1, 4:1}
        >>> switch.teardown()
    """

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    lookup_handler, configured_switches = aliasing_scope(
        name=__name__, lookup_arg="optical_switch_device", lookup_type=OpticalSwitch
    )

    def __init__(self):
        self._facade = OpticalSwitch()

    def setup_optical_switch(self, optical_switch, alias=None, **kwargs):
        # type: (Union[str, Any], Optional[str], **Any) -> OpticalSwitch
        """
        Setup Optical Switch.

        | Example usage with tl object from taf.config.testline:
        | ``switch.setup_optical_switch(tl.optical_switches[0], addr='127.0.0.1')``
        | Example usage without tl object from taf.config.testline:
        | ``switch.setup_optical_switch(optical_switch='Leoni', model='mol 6x(2x6)', addr='127.0.0.1')``
        | Example select Calient based on TL1 protocol:
        | ``switch.setup_optical_switch(optical_switch="Calient", model="S320", addr="127.0.0.1", user_name="tl1user", protocol="tl1")``
        | Example select Calient based on HTTP protocol:
        | ``switch.setup_optical_switch(optical_switch="Calient", model="S320", addr="127.0.0.1", user_name="tl1user", protocol="http")``

        :param Union[str,OpticalSwitch] optical_switch: optical switch device to create.
               If it is a string, it is assumed to represent a vendor.
               Otherwise it is assumed to be a OpticalSwitch object from `taf.config.testline`.
               In that case the program can differentiate vendor, address, model of OpticalSwitch
        :param alias: alias to be used in keywords
        :param kwargs: see documentation of a particular device for details!
        :return: Configured optical switch object, connected to optical switch, if needed.

        """  # noqa: E501
        if isinstance(optical_switch, str):
            if "addr" not in kwargs or "model" not in kwargs:
                exc_msg = "'addr' and 'model' arguments need to be passed " "to 'setup_optical_switch'"
                raise TypeError(exc_msg)

        if "timeout" in kwargs:
            kwargs["timeout"] = time_to_seconds(kwargs["timeout"])
        if "port" in kwargs:
            kwargs["port"] = int(kwargs["port"])

        configured_opt_switch = self._facade.setup_optical_switch(optical_switch, **kwargs)
        self.configured_switches.add(configured_opt_switch, alias)
        return configured_opt_switch

    @lookup_handler.implicit_lookup
    def get_optical_switch_channels(self, optical_switch_device=None):
        # type: (Optional[str]) -> dict
        channels = self._facade.get_channels(optical_switch_device=optical_switch_device)
        return dict(sorted(channels.items()))

    @lookup_handler.implicit_lookup
    def get_optical_switch_connection_details(self, connection, optical_switch_device=None):
        # type: (str, Optional[str]) -> dict

        return self._facade.get_connection_details(connection, optical_switch_device=optical_switch_device)

    @lookup_handler.implicit_lookup
    def set_optical_switch_channels(self, settings, optical_switch_device=None):
        # type: (dict, Optional[str]) -> None

        self._facade.set_channels(settings, optical_switch_device=optical_switch_device)

    @lookup_handler.implicit_lookup
    def set_optical_switch_channel(self, settings, optical_switch_device=None):
        # type: (dict, Optional[str]) -> None

        self._facade.set_channel(settings, optical_switch_device=optical_switch_device)

    @lookup_handler.implicit_lookup
    def remove_optical_switch_connections(self, in_ports=None, out_ports=None, optical_switch_device=None, **kwargs):
        # type: (Optional[list], Optional[list], Optional[str], Optional[bool]) -> None

        self._facade.remove_connections(
            in_ports=in_ports,
            out_ports=out_ports,
            optical_switch_device=optical_switch_device,
            **kwargs,
        )

    @lookup_handler.implicit_lookup
    def remove_all_connections(self, optical_switch_device=None):
        self._facade.remove_all_connections(optical_switch_device=optical_switch_device)

    @lookup_handler.implicit_lookup
    def activate_optical_switch_connection(self, connection, optical_switch_device=None):
        # type: (str, Optional[str]) -> None

        self._facade.activate_connection(connection, optical_switch_device=optical_switch_device)

    @lookup_handler.implicit_lookup
    def deactivate_optical_switch_connection(self, connection, optical_switch_device=None):
        # type: (str, Optional[str]) -> None

        self._facade.deactivate_connection(connection, optical_switch_device=optical_switch_device)

    @lookup_handler.implicit_lookup
    def set_link_flapping(
        self,
        ports,
        lowperiod=None,
        highperiod=None,
        repeat=None,
        duration=None,
        period=None,
        frequency=None,
        optical_switch_device=None,
    ):
        self._facade.set_link_flapping(
            lowperiod=lowperiod,
            highperiod=highperiod,
            period=period,
            frequency=frequency,
            repeat=repeat,
            duration=duration,
            ports=ports,
            optical_switch_device=optical_switch_device,
        )

    @lookup_handler.implicit_lookup
    def set_multiple_cross_connections(self, connection_list, optical_switch_device=None):
        self._facade.set_multiple_cross_connections(
            connection_list=connection_list, optical_switch_device=optical_switch_device
        )

    @lookup_handler.implicit_lookup
    def dropout(self, port, duration, optical_switch_device=None):
        # type: (str, str, Optional[str]) -> None

        self._facade.dropout(port=port, duration=duration, optical_switch_device=optical_switch_device)

    @lookup_handler.implicit_lookup
    def teardown(self, optical_switch_device=None):
        # type: (Optional[str]) -> None

        self._facade.teardown(optical_switch_device)
